contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address target, bytes memory data) public payable {
        require(address(this).balance >= msg.value);
        uint256 balanceBefore = address(this).balance;

        bool commandReverted;
        try c.Command{value: msg.value}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }

        bool callSucceeded = false;
        if (!commandReverted) {
            (bool ok, ) = target.call{value: msg.value}(data);
            callSucceeded = ok;
        }

        assert(commandReverted == !callSucceeded);
        assert(commandReverted || address(this).balance == balanceBefore - msg.value);
    }
}

